const REGISTRY_UNAVAILABLE =
  /^(?:ECONNRESET|ECONNREFUSED|ETIMEDOUT|ECONNECTIONTIMEOUT|EIDLETIMEOUT|ERESPONSETIMEOUT|ETRANSFERTIMEOUT|ERR_SOCKET_TIMEOUT|ENOTFOUND|EAI_AGAIN|EAI_FAIL|E429|E5\\d\\d)$/;
